-- Trap and chessboard templates the spawns above need: SkyFire's use display 1287, which this client's
-- GameObjectDisplayInfo.dbc lacks, so the core would not load them. LoA's display ids (299 = invisible).
UPDATE `gameobject_template` SET `displayId` = 299 WHERE `entry` IN (178194, 181677, 181678, 181695, 185324) AND `displayId` = 1287; -- Lava Crack, Plague Fissures, Chessboard
UPDATE `gameobject_template` SET `displayId` = 0 WHERE `entry` = 181676 AND `displayId` = 1287; -- Plague Fissure
